base_refund br


        and br.org_id in

            #{item}




            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y') <= #{query.endDate}



) br,
(
SELECT
SUM( bbp.received_amount ) AS totalClinicCollectionAmount
FROM
(
SELECT
bbp.received_amount
