        and bbp.org_id in

            #{item}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}


    AND bbp.bill_id NOT IN (
    SELECT
    bb.bill_id
    FROM base_bill bb


            and bb.org_id in

                #{item}



    )

) bbp
) bbp2,
(
SELECT
SUM( bbp.received_amount ) AS totalClinicCollectedAmount
FROM
(
SELECT
bbp.received_amount
FROM
base_bill_pay bbp


        and bbp.org_id NOT IN

            #{item}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




